ROOT = Path(__file__).resolve().parent
sources = json.loads((ROOT / 'source.json').read_text())
references = json.loads((ROOT / 'reference-targets.json').read_text())
answer = copy.deepcopy(json.loads((ROOT / 'previous-answer.json').read_text()))
by_number = {a['number']: a for a in answer}
targets_by_number = {a['number']: (key, a) for key, a in references['targets'].items()}

# Les textes complets du précédent essai constituent le point de départ.
